const item = $json;
const required = ['id','topic','capturedAt','region','channels','evidenceUrl'];
const missing = required.filter((key) => item[key] === undefined || item[key] === '' || (Array.isArray(item[key]) && item[key].length === 0));
const claim = `${item.topic || ''} ${item.draftClaim || ''}`;
const flags = [];
if (missing.length) flags.push(...missing.map((key) => `missing ${key}`));
if (!/^https?:\/\//i.test(item.evidenceUrl || '')) flags.push('evidence:missing');
if (/\b(guaranteed|viral)\b/i.test(claim)) flags.push('claim:human_review');
return [{ json: { ...item, status: flags.length ? 'needs_review' : 'ready_for_brief', flags, localOnly: true } }];
